export function slugify(s) {
  return s.toLowerCase(); // bug: spaces and punctuation are not replaced
}

files.slug.test.mjs:
import { test } from 'node:test';
import assert from 'node:assert';
import { slugify } from './slug.mjs';
test('spaces become hyphens', () => { assert.equal(slugify('Hello World'), 'hello-world'); });
test('punctuation is stripped', () => { assert.equal(slugify('Ship it, now!'), 'ship-it-now'); });
